import{_ as a,o as i,c as l,a2 as s}from"./chunks/framework.D46keoNO.js";const u=JSON.parse('{"title":"快捷键","description":"","frontmatter":{},"headers":[],"relativePath":"guide/shortcuts.md","filePath":"guide/shortcuts.md","lastUpdated":1784107251000}'),e={name:"guide/shortcuts.md"};function o(n,t,d,r,h,p){return i(),l("div",null,[...t[0]||(t[0]=[s(`<h1 id="快捷键" tabindex="-1">快捷键 <a class="header-anchor" href="#快捷键" aria-label="Permalink to &quot;快捷键&quot;">​</a></h1><table tabindex="0"><thead><tr><th>快捷键 (Windows/Linux)</th><th>快捷键 (macOS)</th><th>功能</th><th>说明</th></tr></thead><tbody><tr><td><code>Alt+Shift+T</code></td><td><code>Option+Shift+T</code></td><td>翻译选中文本</td><td>编辑器中选中非英文文本后翻译替换</td></tr><tr><td><code>Alt+Shift+C</code></td><td><code>Option+Shift+C</code></td><td>翻译并复制到剪贴板</td><td>翻译后复制多种格式到剪贴板历史，不替换原文</td></tr><tr><td><code>Alt+Shift+Z</code></td><td><code>Option+Shift+Z</code></td><td>撤回文件翻译</td><td>删除翻译后的文件/目录（1 分钟内有效）</td></tr><tr><td><code>Ctrl+Z</code></td><td><code>Cmd+Z</code></td><td>撤回文件翻译（条件生效）</td><td>仅在 1 分钟内且焦点不在文本输入区（如资源管理器）时生效，编辑器内保持原生文字撤销</td></tr><tr><td><code>Alt+Shift+D</code></td><td><code>Option+Shift+D</code></td><td>切换文件翻译开关</td><td>开启/关闭文件路径翻译功能</td></tr><tr><td><code>Alt+Shift+S</code></td><td><code>Option+Shift+S</code></td><td>切换翻译服务</td><td>在 7 种翻译服务间快速切换</td></tr></tbody></table><p>以上功能也可在编辑器右键菜单中找到（翻译选中文本、翻译并复制需先选中文本）。</p><h2 id="快捷键说明" tabindex="-1">快捷键说明 <a class="header-anchor" href="#快捷键说明" aria-label="Permalink to &quot;快捷键说明&quot;">​</a></h2><h3 id="alt-shift-t-翻译选中文本" tabindex="-1">Alt+Shift+T - 翻译选中文本 <a class="header-anchor" href="#alt-shift-t-翻译选中文本" aria-label="Permalink to &quot;Alt+Shift+T - 翻译选中文本&quot;">​</a></h3><p><strong>生效条件</strong>：编辑器聚焦且有选中文本。</p><p><strong>使用方法</strong>：</p><ol><li>在编辑器中选中非英文文本</li><li>按 <code>Alt+Shift+T</code></li><li>选择翻译格式</li><li>文本自动替换为英文</li></ol><p><strong>支持格式</strong>：</p><ul><li>camelCase</li><li>PascalCase</li><li>snake_case</li><li>CONSTANT_CASE</li><li>param-case</li><li>Header-Case</li><li>Capital Case</li><li>no case</li></ul><p>替换后可用 VSCode 自带的 <code>Ctrl+Z</code> 撤销。</p><h3 id="alt-shift-c-翻译并复制到剪贴板" tabindex="-1">Alt+Shift+C - 翻译并复制到剪贴板 <a class="header-anchor" href="#alt-shift-c-翻译并复制到剪贴板" aria-label="Permalink to &quot;Alt+Shift+C - 翻译并复制到剪贴板&quot;">​</a></h3><p><strong>生效条件</strong>：编辑器聚焦且有选中文本。</p><p><strong>使用方法</strong>：</p><ol><li>在编辑器中选中非英文文本</li><li>按 <code>Alt+Shift+C</code></li><li>选择翻译格式</li><li>翻译结果复制到剪贴板历史，原文本不变</li></ol><p><strong>配置示例</strong>：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;variableTranslator.copyToClipboard&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;variableTranslator.clipboardFormats&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;originalValue&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;camelCase&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;snake_case&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><strong>效果</strong>：选中「用户名称」选择 camelCase 后，剪贴板历史中依次包含：</p><ul><li><code>用户名称</code>（originalValue，原始文本）</li><li><code>userName</code>（camelCase）</li><li><code>user_name</code>（snake_case）</li></ul><p>当前剪贴板保留用户选择的格式（<code>userName</code>），全部格式需通过 <strong>Win+V</strong> 剪贴板历史取用。</p><h3 id="alt-shift-z-ctrl-z-撤回文件翻译" tabindex="-1">Alt+Shift+Z / Ctrl+Z - 撤回文件翻译 <a class="header-anchor" href="#alt-shift-z-ctrl-z-撤回文件翻译" aria-label="Permalink to &quot;Alt+Shift+Z / Ctrl+Z - 撤回文件翻译&quot;">​</a></h3><p><strong>使用方法</strong>：</p><ol><li>文件翻译完成后，按 <code>Alt+Shift+Z</code>（或在资源管理器等非文本输入区按 <code>Ctrl+Z</code>）</li><li>翻译后的文件被删除</li><li>相关编辑器窗口关闭</li></ol><p><strong>注意事项</strong>：</p><ul><li>仅在 <strong>1 分钟内</strong>有效，超时后撤回记录自动清空</li><li><code>Ctrl+Z</code> 仅在存在可撤回记录且焦点不在文本输入区时生效；编辑器内的 <code>Ctrl+Z</code> 始终保持 VSCode 原生文字撤销，不受影响</li><li>撤回完成后到 1 分钟窗口结束前，再次按 <code>Ctrl+Z</code> 会提示“没有可撤回的翻译记录”，而不会触发 VSCode 原生文件撤销（原生撤销栈中“创建原始文件”的记录在翻译重命名后已失效，触发会报错）</li><li>删除的是翻译后的文件，不会恢复原始非英文路径</li><li>仅清理翻译时创建的目录（通过对比翻译前后路径判断，不会删除用户原有目录）</li></ul><h3 id="alt-shift-d-切换文件翻译开关" tabindex="-1">Alt+Shift+D - 切换文件翻译开关 <a class="header-anchor" href="#alt-shift-d-切换文件翻译开关" aria-label="Permalink to &quot;Alt+Shift+D - 切换文件翻译开关&quot;">​</a></h3><p><strong>使用方法</strong>：</p><ol><li>按 <code>Alt+Shift+D</code></li><li>状态栏显示当前状态</li></ol><p><strong>状态说明</strong>：</p><ul><li>开启：文件翻译：已开启 ✓</li><li>关闭：文件翻译：已关闭 ✗</li></ul><p>等价于修改配置项 <code>variableTranslator.enableFileTranslation</code>。</p><h3 id="alt-shift-s-切换翻译服务" tabindex="-1">Alt+Shift+S - 切换翻译服务 <a class="header-anchor" href="#alt-shift-s-切换翻译服务" aria-label="Permalink to &quot;Alt+Shift+S - 切换翻译服务&quot;">​</a></h3><p><strong>使用方法</strong>：</p><ol><li>按 <code>Alt+Shift+S</code></li><li>选择要使用的翻译服务</li></ol><p><strong>可选服务</strong>：</p><ul><li>拼音（零配置，默认）</li><li>ChatGPT / OpenAI</li><li>谷歌翻译</li><li>Bing / Azure Translator</li><li>DeepLX</li><li>百度翻译</li><li>腾讯翻译君</li></ul><p>选择未配置的服务时，插件会提示打开设置页面。</p><h2 id="状态栏显示" tabindex="-1">状态栏显示 <a class="header-anchor" href="#状态栏显示" aria-label="Permalink to &quot;状态栏显示&quot;">​</a></h2><h3 id="文件翻译开关状态" tabindex="-1">文件翻译开关状态 <a class="header-anchor" href="#文件翻译开关状态" aria-label="Permalink to &quot;文件翻译开关状态&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>切换 Alt+Shift+D 时显示：</span></span>
<span class="line"><span>- 开启：文件翻译：已开启 ✓</span></span>
<span class="line"><span>- 关闭：文件翻译：已关闭 ✗</span></span>
<span class="line"><span>- 显示时间：2-3 秒后自动消失</span></span></code></pre></div><h3 id="当前翻译服务" tabindex="-1">当前翻译服务 <a class="header-anchor" href="#当前翻译服务" aria-label="Permalink to &quot;当前翻译服务&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>状态栏显示：</span></span>
<span class="line"><span>[拼音] 文件翻译：已开启 ✓</span></span></code></pre></div><h2 id="修改快捷键" tabindex="-1">修改快捷键 <a class="header-anchor" href="#修改快捷键" aria-label="Permalink to &quot;修改快捷键&quot;">​</a></h2><p>如快捷键与其他插件冲突，可自行修改：</p><ol><li>按 <code>Ctrl+K Ctrl+S</code> 打开键盘快捷方式</li><li>搜索 <code>variableTranslator</code></li><li>双击对应命令重新绑定按键</li></ol>`,45)])])}const g=a(e,[["render",o]]);export{u as __pageData,g as default};
